'use strict';
// V48 : calculs de carrière fictifs ; aucun effet de bord.
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.CDCoachMarket=api})(typeof globalThis==='object'?globalThis:null,function(){const num=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;
function vacancies(clubs,coaches){if(!Array.isArray(clubs)||!Array.isArray(coaches))throw Error('Données invalides');return clubs.filter(c=>c&&typeof c.id==='string'&&num(c.budget)&&num(c.reputation)&&c.reputation<=100&&c.vacant===true).map(c=>({clubId:c.id,options:coaches.filter(m=>m&&typeof m.id==='string'&&num(m.salary)&&num(m.reputation)&&m.reputation<=100&&m.salary<=c.budget&&m.available===true).sort((a,b)=>Math.abs(a.reputation-c.reputation)-Math.abs(b.reputation-c.reputation)||a.id.localeCompare(b.id)).map(m=>m.id)}));}function dismissalRisk({confidence,consecutiveLosses}){if(!num(confidence)||confidence>100||!Number.isInteger(consecutiveLosses)||consecutiveLosses<0)throw Error('Données invalides');return {risk:Math.min(100,Math.round((100-confidence)*.65+Math.min(10,consecutiveLosses)*3)),critical:confidence<25&&consecutiveLosses>=3};}
function forecastRisk({confidence,lossesBySeason}){if(!Array.isArray(lossesBySeason)||lossesBySeason.length>40)throw Error('Historique invalide');let current=confidence;const history=[];for(const losses of lossesBySeason){if(!Number.isInteger(losses)||losses<0||losses>40)throw Error('Défaites invalides');const risk=dismissalRisk({confidence:current,consecutiveLosses:losses});history.push(risk);current=Math.max(0,Math.min(100,current+(losses>=5?-8:losses<=1?4:-2)));}return {history,confidence:current};}
function jobOffers(clubs,coach){if(!Array.isArray(clubs)||!coach||!num(coach.salary)||!num(coach.reputation)||coach.reputation>100)throw Error('Offres invalides');return clubs.filter(c=>c&&c.vacant===true&&typeof c.id==='string'&&num(c.budget)&&num(c.reputation)&&c.reputation<=100&&c.budget>=coach.salary).map(c=>({clubId:c.id,affinity:100-Math.abs(coach.reputation-c.reputation),salaryCap:c.budget})).sort((a,b)=>b.affinity-a.affinity||a.clubId.localeCompare(b.clubId));}
return Object.freeze({jobOffers,forecastRisk,vacancies,dismissalRisk});});
